corrected_code:
from django.contrib.auth.views import PasswordResetConfirmView
from django.http import JsonResponse
from django.utils.http import urlsafe_base64_decode
from django.contrib.auth import get_user_model

User = get_user_model()

class UnifiedPasswordResetConfirmView(PasswordResetConfirmView):
    def post(self, request, *args, **kwargs):
        uidb64 = kwargs.get('uidb64')
        try:
            uid = urlsafe_base64_decode(uidb64).decode()
            target_user = User.objects.get(pk=uid)
        except Exception:
            return JsonResponse({'error': 'Invalid user identifier'}, status=400)

        token = kwargs.get('token')
        # Token must ALWAYS be checked regardless of session authentication state
        if not self.token_generator.check_token(target_user, token):
            return JsonResponse({'error': 'Invalid or expired token'}, status=400)

        new_password = request.POST.get('new_password')
        target_user.set_password(new_password)
        target_user.save()
        return JsonResponse({'success': True})
